insert into public.duas_library (source, source_id, title, arabic_text, transliteration, translation, reference, category, repeat_count, benefit, tags, sort_order, status) values
('fitrahive', 'daily-dua/0', 'Supplication Before Sleeping', 'بِاسْمِكَ اللَّهُمَّ أَمُوْتُ وَأَحْيَا', 'bismika allahumma amutu wa ahya', 'In Your name, O Allah, I die and I live.', 'HR. al-Bukhari', 'sleep', 1, 'The Prophet, sallallahu ''alayhi wa sallam, always started and ended his day with dhikr.', array['sleep']::text[], 0, 'approved'),
('fitrahive', 'daily-dua/1', 'Supplication Upon Waking Up', 'الحَمْدُ للهِ الَّذِي أَحْيَانَا بعْدَ مَا أماتَنَا وإِلَيْهِ النُّشُورُ', 'alhamdulillahilladhi ahyana ba''da ma amatana wa ilayhin-nushur', 'All praise is for Allah who gives us life after He has caused us to die, and to Him is the resurrection.', 'HR. Bukhari: 6327', 'sleep', 1, 'By reciting the supplication above, a servant begins his day by praising the name of Allah, the Giver of Life and the Bringer of Death.', array['sleep','gratitude']::text[], 1, 'approved'),
('fitrahive', 'daily-dua/2', 'Supplication Entering the Bathroom', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ', 'allahumma inni a''udhu bika minal-khubuthi wal-khaba''ith', 'O Allah, I seek refuge in You from the evil and the wicked.', 'HR. al-Bukhari and Muslim', 'purification', 1, 'This supplication acts as a barrier between a servant''s private parts and the jinn when entering the bathroom.', array['purification','protection']::text[], 2, 'approved'),
('fitrahive', 'daily-dua/3', 'Supplication Leaving the Bathroom', 'غُفْرَانَكَ', 'ghufranak', 'I ask for Your forgiveness (O Allah).', 'HR. at-Tirmidzi', 'purification', 1, 'The bathroom is one of the homes of the jinn and devils, so it is recommended to ask for forgiveness for any mistakes, intentional or unintentional, made while in the bathroom.', array['purification','forgiveness']::text[], 3, 'approved'),
('fitrahive', 'daily-dua/4', 'Supplication Before Eating', 'بِسْمِ اللَّهِ', 'bismillah', 'In the name of Allah.', 'HR. al-Bukari No. 5376 and Muslim No. 2022', 'food', 1, 'The benefit of reciting Bismillah before eating is to prevent Satan from joining humans in eating.', array['food']::text[], 4, 'approved'),
('fitrahive', 'daily-dua/5', 'Supplication If Forgetting Bismillah at the Beginning of a Meal', 'بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ', 'bismillahi awwalahu wa akhirahu', 'In the name of Allah, at its beginning and its end.', 'HR. Abu Dawud', 'food', 1, 'Islam pays great attention to etiquette. If someone forgets to recite the supplication before eating at the beginning, it is still recommended to recite it in the middle, even if there is only a spoonful of rice left.', array['food']::text[], 5, 'approved'),
('fitrahive', 'daily-dua/6', 'Supplication After Eating', 'الْحَمْدُ لِلَّهِ الَّذِى أَطْعَمَنِى هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّى وَلاَ قُوَّةٍ', 'alhamdulillahilladhi at''amani hadha wa razaqanihi min ghayri hawlin minni wa la quwwah', 'All praise is to Allah who has fed me this and provided for me without any power or strength from me.', 'Shahih at-Tirmidzi', 'food', 1, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said that if someone recites this supplication, then his past sins will be forgiven.', array['food','gratitude']::text[], 6, 'approved'),
('fitrahive', 'daily-dua/7', 'Supplication Entering the Mosque', 'اَللَّهُمَّ افْتَحْ لِيْ أَبْوَابَ رَحْمَتِكَ', 'allahummaftah li abwaba rahmatik', 'O Allah, open the doors of Your mercy for me.', 'HR. Muslim', 'mosque', 1, 'The mosque is the house of Allah; a servant should honor it and hope for Allah''s mercy within it.', array['mosque']::text[], 7, 'approved'),
('fitrahive', 'daily-dua/8', 'Supplication Leaving the Mosque', 'اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ فَضْلِكَ', 'allahumma inni as''aluka min fadlik', 'O Allah, I ask You for Your bounty.', 'HR. Muslim No. 713', 'mosque', 1, 'Allah''s earth is vast, and there are many ways to seek provision. A servant should ask for Allah''s bounty to be facilitated in obtaining the provision that Allah has distributed to all His servants.', array['mosque']::text[], 8, 'approved'),
('fitrahive', 'daily-dua/9', 'Supplication Before Performing Ablution', 'بِسْمِ اللَّهِ', 'bismillah', 'In the name of Allah.', 'HR. at-Tirmidzi and al-Baihaqi', 'purification', 1, 'It is prescribed to begin every important matter by saying Bismillah, whether it be an act of worship or otherwise.', array['purification']::text[], 9, 'approved'),
('fitrahive', 'daily-dua/10', 'Supplication After Performing Ablution', 'أشْهَدُ أنْ لا إله إِلاَّ اللَّهُ وَحْدَهُ لا شَرِيك لَهُ ، وأشْهَدُ أنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ ، اللَّهُمَّ اجْعَلْنِي مِنَ التَوَّابِينَ ، واجْعَلْني مِنَ المُتَطَهِّرِينَ ، سُبْحانَكَ اللَّهُمَّ وبِحَمْدِكَ ، أشْهَدُ أنْ لا إلهَ إِلاَّ أنْتَ ، أسْتَغْفِرُكَ وأتُوبُ إِلَيْكَ', 'ashhadu alla ilaha illa allah wahdahu la sharika lahu, wa ashhadu anna muhammadan ''abduhu wa rasuluh. allahummaj''alni minat-tawwabina waj''alni minal-mutatahhirin. subhanakallahumma wa bihamdika ashhadu alla ilaha illa anta astaghfiruka wa atubu ilayk', 'I bear witness that there is no deity except Allah alone, with no partner, and I bear witness that Muhammad is His servant and Messenger. O Allah, make me among those who repent and make me among those who purify themselves. Glory be to You, O Allah, and with Your praise, I bear witness that there is no deity except You. I seek Your forgiveness and repent to You.', 'HR. Muslim, at-Tirmidzi and an-Nasa''i', 'purification', 1, 'Whoever recites this supplication, eight gates of Paradise will be opened for him, and he may enter from whichever gate he wishes.', array['purification']::text[], 10, 'approved'),
('fitrahive', 'daily-dua/11', 'Supplication for Breaking the Fast', 'ذَهَبَ الظَّمَأُ وابْتَلَّتِ الْعُرُوقُ وثَبَتَ اْلأَجْرُ إِنْ شَاءَاللهُ', 'dhahabadh-dhama''u wabtallatil-''uruqu wa thabatal-ajru insha allah', 'The thirst has gone, the veins are moistened, and the reward is confirmed, Insha Allah.', 'HR. Abu Daud, As-Sunan Al-Kubra Lil Baihaqi, Vol. 4, p. 239, al-Hakim in Mustadrak ''alas Shahihain No. 1484', 'fasting', 1, 'It is highly recommended for those who are fasting to increase their supplications before and after breaking the fast, because the supplication of a fasting person is one of the three supplications that are not rejected.', array['fasting','gratitude']::text[], 11, 'approved'),
('fitrahive', 'daily-dua/12', 'Supplication Entering the House #1', 'اَلسَّلَامُ عَلَيْكُمْ', 'assalamu ''alaykum', 'Peace be upon you.', 'HR. at-Tirmidzi', 'home', 1, 'The greeting is a supplication of hope, a hope that you will be safe from all kinds of sorrow and suffering, and be enveloped in mercy and blessings.', array['home','marriage']::text[], 12, 'approved'),
('fitrahive', 'daily-dua/13', 'Supplication Entering the House #2', 'اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَا تُهُ', 'assalamu ''alaykum wa rahmatullahi wa barakatuh', 'Peace, mercy, and blessings of Allah be upon you.', 'HR. at-Tirmidzi', 'home', 1, 'The greeting is a supplication of hope, a hope that you will be safe from all kinds of sorrow and suffering, and be enveloped in mercy and blessings.', array['home','marriage']::text[], 13, 'approved'),
('fitrahive', 'daily-dua/14', 'Supplication Leaving the House', 'بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ', 'bismillah, tawakkaltu ''alallah, la hawla wa la quwwata illa billah', 'In the name of Allah, I place my trust in Allah. There is no might nor power except with Allah.', 'HR. Abu Dawud and at-Tirmidzi', 'home', 1, 'Whoever recites this supplication, it will be said to him: "You will be guided, sufficed, and protected." Satan will then depart from him. Another satan will say: "How can you harm someone who has been guided, sufficed, and protected?!"', array['home','protection']::text[], 14, 'approved'),
('fitrahive', 'daily-dua/15', 'Supplication for Protection from Causing or Experiencing Harm Outside the House', 'اللَّهُمَّ إِنِّى أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ أَوْ أَزِلَّ أَوْ أُزَلَّ أَوْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَىَّ', 'allahumma inni a''udhu bika an adilla aw udalla, aw azilla aw uzalla, aw adhlima aw udhlama, aw ajhala aw yujhala ''alayya', 'O Allah, I seek refuge in You lest I should stray or be led astray, slip or be tripped, wrong or be wronged, or act foolishly or have foolishness done to me.', 'HR. Abu Dawud, at-Tirmidzi, Ibn Majah and an-Nasa''i', 'protection', 1, 'When a person leaves the house, they will encounter all kinds of things, both good and bad, especially harm caused by themselves. Therefore, it is commanded to seek refuge from oneself and from others.', array['protection','travel']::text[], 15, 'approved'),
('fitrahive', 'daily-dua/16', 'Travel Supplication', 'الله أَكْبَرُ،الله أَكْبَرُ،الله أَكْبَرُ،سُبْحَانَ الَّذِى سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ اللَّهُمَّ إِنَّا نَسْأَلُكَ فِى سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِى السَّفَرِ وَالْخَلِيفَةُ فِى الأَهْلِ اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ فِى الْمَالِ وَالأَهْلِ', 'allahu akbar, allahu akbar, allahu akbar. subhanalladhi sakhkhara lana hadha wa ma kunna lahu muqrinin wa inna ila rabbina lamunqalibun. allahumma inna nas''aluka fi safarina hadhal-birra wat-taqwa wa minal-''amali ma tarda. allahumma hawwin ''alayna safarana hadha watwi ''anna bu''dah. allahumma antas-sahibu fis-safar. wal-khalifatu fil-ahl. allahumma inni a''udhu bika min wa''tha''is-safar wa ka''abatil-mandhari wa su''il-munqalabi fil-mali wal-ahl', 'Allah is the Greatest, Allah is the Greatest, Allah is the Greatest. Glory be to Him who has provided this for us, though we could never have had it by our own efforts. Surely to our Lord we are returning. O Allah, we ask You for righteousness and piety in this journey of ours, and for deeds that please You. O Allah, lighten for us the hardship of this journey and quickly bring us to our destination. O Allah, You are our Companion on the journey and the Guardian of our families. O Allah, I seek refuge in You from the hardship of travel, from a bad return, and from seeing something unpleasant concerning our wealth, family, or children.', 'HR. Muslim', 'travel', 1, 'This supplication has two parts. The first is praise of Allah and the submission of the servant. The second is a request to Allah for ease in travel and in the affairs of what the servant has left at home.', array['travel','protection']::text[], 16, 'approved'),
('fitrahive', 'daily-dua/17', 'Supplication of a Resident for Someone Who is Traveling', 'أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ', 'astawdi''ullaha dinaka, wa amanataka, wa khawatima ''amalik', 'I entrust your religion, your trust, and the end of your deeds to Allah.', 'HR. Abu Dawud: 2601', 'travel', 1, 'Three priorities of a servant that must be maintained everywhere: religion, trust, and deeds, because a person will be resurrected according to their deeds.', array['travel','protection']::text[], 17, 'approved'),
('fitrahive', 'daily-dua/18', 'Supplication for Piety from a Resident to Someone Who is Traveling', 'زَوَّدَكَ اللَّهُ التَّقْوَى وَغَفَرَ ذَنْبَكَ  وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ', 'zawwadakallahut-taqwa, wa ghafara dhanbaka, wa yassara lakal-khayra haythuma kunta', 'May Allah provide you with piety, forgive your sins, and ease goodness for you wherever you are.', 'HR. at-Tirmidzi', 'travel', 1, 'Piety is the best provision that a servant must prepare for the Hereafter, because there is no salvation except through piety.', array['travel','protection']::text[], 18, 'approved'),
('fitrahive', 'daily-dua/19', 'Supplication When Wearing New Clothes', 'اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ', 'allahumma lakal-hamdu anta kasawtanihi. as''aluka min khayrihi wa khayri ma suni''a lah, wa a''udhu bika min sharrihi wa sharri ma suni''a lah', 'O Allah, to You is all praise. You have clothed me with this. I ask You for its goodness and the goodness for which it was made, and I seek refuge in You from its evil and the evil for which it was made.', 'HR. Ahmad, Abu Dawud, at-Tirmidzi and Al-Hakim', 'clothing', 1, 'By reciting this supplication, one asks that the clothes they have bought may provide goodness and also be a protection against various evils.', array['clothing','gratitude']::text[], 19, 'approved'),
('fitrahive', 'daily-dua/20', 'Supplication When Wearing Clothes', 'الْحَمْدُ لِلَّهِ الَّذِى كَسَانِى هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّى وَلاَ قُوَّةٍ', 'alhamdulillahilladhi kasani hadha wa razaqanihi min ghayri hawlin minni wa la quwwah', 'Praise be to Allah who has clothed me with this garment and provided it for me without any power or strength from me.', 'HR. all compilers of Sunan books, except Nasa''i', 'clothing', 1, 'The virtue of reciting this supplication is that past sins will be forgiven, Insha Allah.', array['clothing','gratitude']::text[], 20, 'approved'),
('fitrahive', 'daily-dua/21', 'Supplication When Mounting a Vehicle', 'بِسْمِ اللَّهِ، بِسْمِ اللَّهِ، بِسْمِ اللَّهِ، الحَمْدُ للِه، سُبْحَانَ الَّذِى سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، سُبْحَانَكَ إِنِّى قَدْ ظَلَمْتُ نَفْسِى فَاغْفِرْ لِى فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ', 'bismillah, bismillah, bismillah, alhamdulillah, subhanalladhi sakhkhara lana hadha wa ma kunna lahu muqrinin. wa inna ila rabbina lamunqalibun. subhanaka inni qad dhalamtu nafsi, faghfir li fa innahu la yaghfirudh-dhunuba illa anta', 'In the name of Allah, in the name of Allah, in the name of Allah. All praise is to Allah. Glory be to Him who has subjected this to us, and we could not have done so by ourselves. And indeed, to our Lord we will return. Glory be to You, indeed I have wronged myself, so forgive me, for none can forgive sins except You.', 'HR. Abu Dawud and at-Tirmidzi', 'travel', 1, 'By reciting the supplication for mounting a vehicle, our journey will always be under the protection of Allah. In addition, we will also receive rewards, help, and a calmer heart.', array['travel','protection']::text[], 21, 'approved'),
('fitrahive', 'daily-dua/22', 'Supplication When it Rains', 'اللَّهُمَّ صَيِّبًا نَافِعًا', 'allahumma sayyiban nafi''a', 'O Allah, make it a beneficial rain.', 'HR. al-Bukhari No. 1032', 'weather', 1, 'It is encouraged to pray when it rains so that goodness and blessings increase, as well as its benefits.', array['weather']::text[], 22, 'approved'),
('fitrahive', 'daily-dua/23', 'Supplication During Heavy Rain', 'اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ، اللَّهُمَّ عَلَى الآكَامِ وَالظِّرَابِ وَبُطُونِ الأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ', 'allahumma hawalayna wa la ''alayna. allahumma ''alal-akami wadh-dhirabi, wa butunil-awdiyati, wa manabitish-shajar', 'O Allah, (let the rain fall) around us, not on us. O Allah, (let it fall) on the hills, mountains, small mountains, valleys, and places where trees grow.', 'HR. al-Bukhari No. 1014', 'weather', 1, 'The supplication above is recited when the rain gets heavier or there is a concern that the rain will cause harm.', array['weather']::text[], 23, 'approved'),
('fitrahive', 'daily-dua/24', 'Supplication After it Rains', 'مُطِرْنا بفَضْلِ اللهِ ورَحْمَتِهِ', 'mutirna bi fadlillahi wa rahmatih', 'We have been given rain by the bounty and mercy of Allah.', 'HR. al-Bukhari No. 846 and Muslim No. 71', 'weather', 1, 'By reciting this supplication, one believes that rain falls by the will of Allah (Allah''s virtue), not by the stars, so they do not become disbelievers in Allah.', array['weather']::text[], 24, 'approved'),
('fitrahive', 'daily-dua/25', 'Supplication During Strong Wind', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَأَعُوْذُ بِكَ مِنْ شَرِّهَا', 'allahumma inni as''aluka khayraha wa a''udhu bika min sharriha', 'O Allah, I ask You for the good of this wind, and I seek refuge in You from its evil.', 'HR. Abu Dawud and Ibn Majah', 'weather', 1, 'Among the signs of Allah''s power is a strong wind that can bring blessings and punishment, namely good and bad. Therefore, a servant should continue to ask for good and seek refuge from all harm.', array['weather','protection']::text[], 25, 'approved'),
('fitrahive', 'daily-dua/26', 'The Best Supplication for Seeking Forgiveness (Sayyid al-Istighfar)', 'اَللَّهُمَّ أَنْتَ رَبِّيْ ، لَا إِلٰـهَ إِلاَّ أَنْتَ خَلَقْتَنِيْ وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوْءُ لَكَ بِنِعْمتِكَ عَلَيَّ ، وَأَبُوْءُ بِذَنْبِيْ فَاغْفِرْ لِيْ ، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ', 'allahumma anta rabbi la ilaha illa anta khalaqtani wa ana ''abduka wa ana ''ala ''ahdika wa wa''dika mastata''tu a''udhu bika min sharri ma sana''tu abu''u laka bini''matika ''alayya wa abu''u bidhanbi faghfir li fa innahu la yaghfirudh-dhunuba illa anta', 'O Allah, You are my Lord. There is no deity worthy of worship except You. You created me, and I am Your servant. I abide to Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your blessings upon me, and I acknowledge my sin. So forgive me, for none can forgive sins except You.', 'HR. al-Bukhari No. 6306, 6323, Ahmad IV/122-125, an-Nasa''i VIII/279-280', 'forgiveness', 1, 'Whoever recites it with certainty in the evening, and then he dies, he will enter Paradise, and likewise if (recited) in the morning.', array['forgiveness','dhikr']::text[], 26, 'approved'),
('fitrahive', 'daily-dua/27', 'Supplication for Ease in All Matters', 'اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً وَأَنْتَ تَجْعَلُ الحَزْنَ إِذَا شِئْتَ سَهْلاً', 'allahumma la sahla illa ma ja''altahu sahla, wa anta taj''alul-hazna idha shi''ta sahla', 'O Allah, there is no ease except in that which You make easy, and You make the difficult easy if You wish.', 'HR. Ibn Hibban', 'distress', 1, 'Ease comes only from Allah. Even something difficult can become easy Insha Allah.', array['distress']::text[], 27, 'approved'),
('fitrahive', 'daily-dua/28', 'Supplication When Afflicted by Calamity', 'إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ أْجُرْنِى فِى مُصِيبَتِى وَأَخْلِفْ لِى خَيْرًا مِنْهَا', 'inna lillahi wa inna ilayhi raji''un. allahumma''jurni fi musibati wa akhlif li khayran minha', 'Indeed we belong to Allah, and indeed to Him we will return. O Allah, reward me for my affliction and replace it with something better.', 'HR. Muslim', 'distress', 1, 'A servant should recite the supplication above when afflicted by calamity with certainty and hope. Insha Allah, with this, they will receive a better replacement.', array['grief','distress']::text[], 28, 'approved'),
('fitrahive', 'daily-dua/29', 'Supplication When in Debt', 'اللَّهُمَّ اكْفِنِى بِحَلاَلِكَ عَنْ حَرَامِكَ وَأَغْنِنِى بِفَضْلِكَ عَمَّنْ سِوَاكَ', 'allahummakfini bi halalika ''an haramik, wa aghnini bi fadlika ''amman siwak', 'O Allah, suffice me with what is lawful and keep me away from what is unlawful, and enrich me with Your bounty so I do not depend on anyone besides You.', 'HR. at-Tirmidzi No. 2563', 'distress', 1, 'Lawful provision, even if it is little, is better than abundant unlawful wealth.', array['distress']::text[], 29, 'approved'),
('fitrahive', 'daily-dua/30', 'Supplication for Protection from Laziness, Sadness, and Debt', 'اَللّٰهُمَّ إِنِّى أَعُوْذُبِكَ مِنَ الْهَمِّ وَالْحَزْنِ وَأَعُوْذُبِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَأَعُوْذُبِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَأَعُوْذُبِكَ مِنْ غَلَبَتِ الدَّيْنِ وَقَهْرِ الرجال', 'allahumma inni a''udhu bika minal-hammi wal-hazan. wa a''udhu bika minal-''ajzi wal-kasal. wa a''udhu bika minal-jubni wal-bukhl. wa a''udhu bika min ghalabatid-dayni wa qahrir-rijal', 'O Allah, I seek refuge in You from anxiety and grief, and I seek refuge in You from incapacity and laziness, and I seek refuge in You from cowardice and miserliness, and I seek refuge in You from being overpowered by debt and from being overcome by men.', 'HR. Abu Dawud No. 1555', 'distress', 1, 'Abu Umamah then narrated: After I practiced this supplication, Allah truly removed my anxiety and gave me the ability to repay my debt.', array['distress','protection']::text[], 30, 'approved'),
('fitrahive', 'daily-dua/31', 'Supplication After Sneezing', 'الحَمْدُ للهِ', 'alhamdulillah', 'All praise is to Allah.', 'HR. al-Bukhari', 'sneezing', 1, 'Indeed, Allah loves sneezing because it moves a person to worship. It is encouraged to respond to the praise of Allah by someone who praises Allah, and vice versa.', array['sneezing','gratitude']::text[], 31, 'approved'),
('fitrahive', 'daily-dua/32', 'Supplication Upon Hearing Someone Sneeze', 'يَرْحَمُكَ اللهُ', 'yarhamukallah', 'May Allah have mercy on you.', 'HR. al-Bukhari', 'sneezing', 1, 'Indeed, Allah loves sneezing because it moves a person to worship. It is encouraged to respond to the praise of Allah by someone who praises Allah, and vice versa.', array['sneezing']::text[], 32, 'approved'),
('fitrahive', 'daily-dua/33', 'Response to Someone Who Says ''Yarhamukallah'' After You Sneeze', 'يَهْدِيكُمُ اللهُ وَيُصْلِحُ بَالَكُمْ', 'yahdikumullah wa yuslihu balakum', 'May Allah guide you and improve your condition.', 'HR. al-Bukhari', 'sneezing', 1, 'Indeed, Allah loves sneezing because it moves a person to worship. It is encouraged to respond to the praise of Allah by someone who praises Allah, and vice versa.', array['sneezing']::text[], 33, 'approved'),
('fitrahive', 'daily-dua/34', 'Supplication for Good Character', 'اللَّهُمَّ كَمَا حَسَّنْتَ خَلْقِي فَحَسِّنْ خُلُقِي', 'allahumma kama hassanta khalqi fahassin khuluqi', 'O Allah, just as You have made my external form good, make my character good as well.', 'HR. Ahmad, authenticated by al-Albani in al-Irwa'', 1/115', 'character', 1, 'A charming appearance is not enough provision for a Muslim, but it must be accompanied by noble character. Therefore, a Muslim should constantly ask for their character to be improved and beautified.', array['character']::text[], 34, 'approved'),
('fitrahive', 'daily-dua/35', 'Prayer for Protection from Satan', 'رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَأَعُوْذُ بِكَ رَبِّ أَنْ يَحْضُرُوْنِ', 'rabbi a''udhu bika min hamazatish-shayatin wa a''udhu bika rabbi ay-yahdurun', 'My Lord, I seek refuge in You from the whispers of Satan, and I seek refuge in You, my Lord, from their presence around me.', 'QS. Al-Mu''minun: 97-98', 'protection', 1, 'Indeed, Allah commands the Prophet Muhammad and all his followers to seek refuge from the whispers of Satan in all activities, especially when approaching death. Satan whispers evil into the hearts of humans, encouraging wrongdoing.', array['protection']::text[], 35, 'approved'),
('fitrahive', 'daily-dua/36', 'Prayer After the Adhan', 'اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ', 'allahumma rabba hadhihid-da''watit-tammah, was-salatil-qa''imah, ati muhammadanil-wasilata wal-fadilah, wab''ath-hu maqaman mahmudanilladhi wa''adtah', 'O Allah, Lord of this perfect call and the established prayer, grant Muhammad the wasilah (a high status in Paradise) and the excellence (above all creation), and raise him to the praiseworthy station that You have promised him.', 'Narrated by Abu Dawud (529), at-Tirmidhi (211), an-Nasa''i (2:26), Ibn Majah (722)', 'adhan', 1, 'This prayer is recommended by the Prophet Muhammad sallallahu ''alayhi wa sallam for those who hear the call to prayer. It has many benefits, including receiving intercession from the Prophet on the Day of Judgment, attaining the wasilah and honor in Paradise for the Prophet, and receiving great and commendable reward from Allah. It is also a way to show respect and admiration for Allah and His Messenger, expressing love and longing for the Prophet Muhammad, the role model for Muslims.', array['adhan','dhikr']::text[], 36, 'approved'),
('fitrahive', 'daily-dua/37', 'Prayer for Forgiveness for Parents', 'رَبَّنَا ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ ٱلْحِسَابُ', 'rabbanaghfir li wa liwalidayya wa lil-mu''minina yawma yaqumul-hisab', 'Our Lord, forgive me and my parents and all the believers on the Day the account is established.', 'QS. Ibrahim: 41', 'parents', 1, 'This is a prayer of Prophet Ibrahim (peace be upon him), teaching us to honor and love our parents, remember the Day of Judgment, and care for fellow believers. By making this prayer, we hope that Allah will forgive our sins and make us among the faithful.', array['parents','forgiveness']::text[], 37, 'approved'),
('fitrahive', 'selected-dua/0', 'Dua Seeking Good In This World And In The Hereafter', 'رَبَّنَا آَتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآَخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ''adhaban-nar', 'Our Lord! Give us good in this world and give us good in the Hereafter, and save us from the torment of the hell fire.', 'QS. Al-Baqarah: 201, al-Bukhari: 6389, HR. Muslim: 2690', 'guidance', 1, 'This dua is the dua most often said by the Prophet sallallahu ''alayhi wa sallam, as told by sahaba Anas bin Malik radhiallahu anhu.', array['marriage','gratitude','guidance']::text[], 0, 'approved'),
('fitrahive', 'selected-dua/1', 'Dua To Make Heart Firm Upon Deen #1', 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِى عَلَى دِينِكَ', 'ya muqallibal-qulubi thabbit qalbi ''ala dinik', 'O Changer of the hearts, make my heart firm upon Your religion.', 'HR. at-Tirmidzi, No. 3522 and Ahmad, 6: 315', 'guidance', 1, 'A person''s heart is between the fingers of Allah ta''ala, and He turns it back and forth according to his will. So, it is appropriate for someone to always ask that Allah will set their heart on goodness, and always be istiqamah in the truth.', array['guidance']::text[], 1, 'approved'),
('fitrahive', 'selected-dua/2', 'Dua To Make Heart Firm Upon Deen #2', 'اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ', 'allahumma musarrifal-qulubi sarrif qulubana ''ala ta''atik', 'O Allah! Controller of the hearts, direct our hearts to Your obedience.', 'HR. Muslim No. 2654', 'guidance', 1, 'A person''s heart is between the fingers of Allah ta''ala, and He turns it back and forth according to his will. So, it is appropriate for someone to always ask that Allah will set their heart on goodness, and always be istiqamah in the truth.', array['guidance']::text[], 2, 'approved'),
('fitrahive', 'selected-dua/3', 'Dua To Make Heart Firm Upon Deen #3', 'رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا', 'rabbana la tuzigh qulubana ba''da idh hadaytana', 'O our Lord, do not make our hearts incline to error after You have guided us.', 'QS. Ali Imran: 8', 'guidance', 1, 'A person''s heart is between the fingers of Allah ta''ala, and He turns it back and forth according to his will. So, it is appropriate for someone to always ask that Allah will set their heart on goodness, and always be istiqamah in the truth.', array['guidance']::text[], 3, 'approved'),
('fitrahive', 'selected-dua/4', 'Dua To Seek Refuge Against The Loss Of Pleasure', 'اللَّهُمَّ إِنِّى أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ', 'allahumma inni a''udhu bika min zawali ni''matik, wa tahawwuli ''afiyatik, wa fuja''ati niqmatik, wa jami''i sakhatik', 'O Allah, I seek refuge in You from the loss of the pleasures that You have bestowed, from changes in the health that You have bestowed, from Your sudden torment, and from all Your wrath.', 'HR. Muslim No. 2739', 'protection', 1, 'The pleasures of being present at this time are very likely to be lost, the health of our souls and bodies in a blink of an eye can turn into illness, and only Allah can prevent that from happening.', array['protection','gratitude']::text[], 4, 'approved'),
('fitrahive', 'selected-dua/5', 'Dua To Resist Affliction', 'اللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ جَهْدِ البَلاَءِ ، وَدَرَكِ الشَّقَاءِ ، وَسُوءِ القَضَاءِ ، وَشَمَاتَةِ الأَعْدَاء', 'allahumma inni a''udhu bika min jahdil-bala'', wa darakish-shaqa'', wa su''il-qada'', wa shamatatil-a''da''', 'O Allah, I seek refuge in You from severe calamity, being overtaken by misery, evil destiny, and the triumphant mockery of enemies.', 'HR. al-Bukhari: 6616, Muslim: 2707', 'protection', 1, 'Taking refuge from the provisions of fate that have a bad impact, does not contradict the attitude of being pleased with the provisions of the destiny of Allah azza wa jalla. Because asking for protection from the provision of Allah''s destiny. Allah azza wa jalla could have predestined a disaster for someone, but Allah azza wa jalla also predestined that if he prays, Allah will remove the disaster.', array['protection','distress']::text[], 5, 'approved'),
('fitrahive', 'selected-dua/6', 'Dua To Be Released From Debt, Anxiety, Weakness, Laziness, Fear, And Pressure from Others', 'اَللّٰهُمَّ إِنِّى أَعُوْذُبِكَ مِنَ الْهَمِّ وَالْحَزْنِ وَأَعُوْذُبِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَأَعُوْذُبِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَأَعُوْذُبِكَ مِنْ غَلَبَتِ الدَّيْنِ وَقَهْرِ الرجال', 'allahumma inni a''udhu bika minal-hammi wal-huzni wa a''udhu bika minal-''ajzi wal-kasali wa a''udhu bika minal-jubni wal-bukhli wa a''udhu bika min ghalabatid-dayni wa qahrir-rijal', 'O Allah, I seek refuge in You from care and grief, I seek refuge in You from incapacity and slackness, I seek refuge in You from cowardice and niggardliness, and I seek refuge in You from being overcome by debt and being put in subjection by men.', 'HR. Abu Dawud No. 1555', 'distress', 1, 'A noble sahaba, Abu Umamah, who narrated this hadith, said: after I practiced this prayer, Allah completely removed my confusion and gave me the ability to pay off debts.', array['distress','protection']::text[], 6, 'approved'),
('fitrahive', 'selected-dua/7', 'Dua When Getting Good News', 'الْحَمْدُ لِلَّهِ الَّذِى بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ', 'alhamdu lillahi alladhi bini''matihi tattimmu assalihat', 'Praise be to Allah, by whose grace goodness is perfected.', 'HR. Ibn Majah in the Sunan, No. 3803 and al-Hakim in al-Mustadrak (1/499)', 'gratitude', 1, 'Aisha radhiyallahu ''anha said, Rasulullah sallallahu ''alayhi wa sallam when he saw something he liked, he read the sentence above.', array['gratitude']::text[], 7, 'approved'),
('fitrahive', 'morning-dhikr/0', 'Ayatul Kursi', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'allahu la ilaha illa huwa, al-hayyul-qayyum. la ta''khudhuhu sinatun wa la nawm. lahu ma fis-samawati wa ma fil-ard. man dhal-ladhi yashfa''u ''indahu illa bi-idhnihi. ya''lamu ma bayna aydihim wa ma khalfahum. wa la yuhituna bishay''in min ''ilmihi illa bima sha''. wa si''a kursiyyuhu as-samawati wal-ard. wa la ya''udu-hu hifdhuhuma. wa huwa al-''aliyyul-''azim', 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most Hight, the Most Great.', 'HR. at-Tirmidzi: 2879', 'morning', 1, 'Whoever reads this verse in the morning, he will be protected until evening. And whoever reads it in the evening, he will be protected until morning.', array['dhikr','morning']::text[], 0, 'approved'),
('fitrahive', 'morning-dhikr/1', 'Al-Ikhlas', 'قُلْ هُوَ ٱللَّهُ أَحَدٌ (1) ٱللَّهُ ٱلصَّمَدُ (2) لَمْ يَلِدْ وَلَمْ يُولَدْ (3) وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ (4)', 'qul huwa allahu ahad (1) allahu samad (2) lam yalid wa lam yulad (3) wa lam yakun lahu kufuwan ahad (4)', 'Say, "He is Allah, [who is] One, (1) Allah, the Eternal Refuge. (2) He neither begets nor is born, (3) Nor is there to Him any equivalent." (4)', 'HR. Abu Dawud No. 4241', 'morning', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','morning']::text[], 1, 'approved'),
('fitrahive', 'morning-dhikr/2', 'Al-Falaq', 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ (1) مِن شَرِّ مَا خَلَقَ (2) وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ (3) وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ (4) وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ (5)', 'qul a''udhu birabbil-falaq (1) min sharri ma khalaq (2) wa min sharri ghasiqin idha waqab (3) wa min sharri naffathati fil-''uqad (4) wa min sharri hasidin idha hasad (5)', 'Say, "I seek refuge in the Lord of daybreak (1) From the evil of that which He created (2) And from the evil of darkness when it settles (3) And from the evil of the blowers in knots (4) And from the evil of an envier when he envies." (5)', 'HR. Abu Dawud No. 4241', 'morning', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','morning']::text[], 2, 'approved'),
('fitrahive', 'morning-dhikr/3', 'An-Nas', 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ (1) مَلِكِ ٱلنَّاسِ (2) إِلَٰهِ ٱلنَّاسِ (3) مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ (4) ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ (5) مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ (6)', 'qul a''udhu birabbin-nas (1) malikin-nas (2) ilahin-nas (3) min sharri al-waswasi al-khannas (4) alladhi yuwaswisu fi sudurin-nas (5) mina al-jinnati wan-nas (6)', 'Say, "I seek refuge in the Lord of mankind, (1) The King of mankind. (2) The God of mankind, (3) From the evil of the whisperer who withdraws, (4) Who whispers in the breasts of mankind, (5) Of the jinn and mankind." (6)', 'HR. Abu Dawud No. 4241', 'morning', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','morning']::text[], 3, 'approved'),
('fitrahive', 'morning-dhikr/4', 'Upon Entering The Morning by Asking for Protection from Allah', 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ. رَبِّ أَسْأَلُكَ خَيْرَ مَا فِيْ هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيْ هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ، رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', 'asbahna wa asbahal-mulku lillahi, wal-hamdu lillahi, la ilaha illa allah wahdahu la sharika lahu, lahu al-mulku wa lahu al-hamdu wa huwa ''ala kulli shay''in qadir. rabbi as''aluka khayra ma fi hadha al-yawm wa khayra ma ba''dahu, wa a''udhu bika min sharri ma fi hadha al-yawm wa sharri ma ba''dahu. rabbi a''udhu bika mina al-kasali wa su''il-kibar. rabbi a''udhu bika min ''adhabin fin-nar wa ''adhabin fil-qabr', 'We have entered the morning and the dominion belongs to Allah, and all praise is for Allah. There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs the dominion and to Him is praise, and He is over all things competent. My Lord, I ask You for the good of this day and the good of what follows it, and I seek refuge in You from the evil of this day and the evil of what follows it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from the punishment of the Fire and the punishment of the grave.', 'HR. Muslim No. 2723 (75), Abu Dawud No. 5071, and at-Tirmidzi 3390, sahih from Abdullah Ibn Mas''ud', 'morning', 1, 'Asking for protection from evil takes precedence, the rule that shows the importance of this is: "Preventing harm is more important and takes precedence than bringing good".', array['dhikr','morning']::text[], 4, 'approved'),
('fitrahive', 'morning-dhikr/5', 'Upon Entering The Morning with The Grace of Allah', 'اَللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوْتُ وَإِلَيْكَ النُّشُوْرُ', 'allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namutu wa ilaykan-nushur', 'O Allah, with Your grace and help we enter the morning, and with Your grace and help we enter the evening. By Your grace and will we live and by Your grace and will we die. And to You is the resurrection (for all creatures).', 'HR. al-Bukhari in al-Adab al-Mufrad No. 1199, this wording is the wording of al-Bukhari, at-Tirmidzi No. 3391, Abu Dawud No. 5068, Ahmad 11/354, Ibn Majah No. 3868', 'morning', 1, 'Everything we do from morning to evening, from when we start our life until we die, is all under the control of Allah and to Him we return.', array['dhikr','morning']::text[], 5, 'approved'),
('fitrahive', 'morning-dhikr/6', 'Sayyid al-Istighfar', 'اَللَّهُمَّ أَنْتَ رَبِّيْ ، لَا إِلٰـهَ إِلاَّ أَنْتَ خَلَقْتَنِيْ وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوْءُ لَكَ بِنِعْمتِكَ عَلَيَّ ، وَأَبُوْءُ بِذَنْبِيْ فَاغْفِرْ لِيْ ، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ', 'allahumma anta rabbi, la ilaha illa anta, khalaqtani wa ana ''abduka, wa ana ''ala ''ahdika wa wa''dika mastata''tu. a''udhu bika min sharri ma sana''tu, abu''u laka bini''matika ''alayya, wa abu''u bidhanbi faghfir li, fa innahu la yaghfirudh-dhunuba illa anta', 'O Allah, You are my Lord. There is no deity worthy of worship except You. You created me and I am Your servant. I will be true to my covenant and promise to You as much as I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favor upon me and I acknowledge my sin, therefore, forgive me. Indeed, there is no one who can forgive sins except You.', 'HR. al-Bukhari No. 6306, 6323, Ahmad IV/122-125, an-Nasa''i VIII/279-280', 'morning', 1, 'Whoever reads it with confidence in the evening, then he dies, he will enter heaven, so also if (read) in the morning.', array['dhikr','morning']::text[], 6, 'approved'),
('fitrahive', 'morning-dhikr/7', 'Dua for Protection and Good Health', 'اَللَّهُمَّ عَافِنِيْ فِيْ بَدَنِيْ ، اَللَّهُمَّ عَافِنِيْ فِيْ سَمْعِيْ ، اَللَّهُمَّ عَافِنِيْ فِيْ بَصَرِيْ ، لَا إِلَـهَ إِلَّا أَنْتَ ، اَللَّهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِوَالْفَقْرِ ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ، لَا إِلَـهَ إِلَّا أَنْتَ', 'allahumma ''afini fi badani, allahumma ''afini fi sam''i, allahumma ''afini fi basari, la ilaha illa anta. allahumma inni a''udhu bika minal-kufri wal-faqr, wa a''udhu bika min ''adhabil-qabr, la ilaha illa anta', 'O Allah, protect my body (from illness and from what I do not want). O Allah, protect my hearing (from illness and disobedience or from what I do not want). O Allah, protect my sight, there is no deity worthy of worship except You. O Allah, indeed I seek refuge in You from disbelief and poverty. I seek refuge in You from the punishment of the grave, there is no deity worthy of worship except You.', 'HR. al-Bukhari in Sahih al-Adab al-Mufrad No. 701, Abu Dawud No. 5090, Ahmad V/42, hasan', 'morning', 1, 'By asking Allah to grant us well-being in our body, we are asking to be cured from all physical and spritual ailments, so that we possess both a healthy body and a pure heart, and therefore use this healthy body in a way that pleases Allah.', array['dhikr','morning']::text[], 7, 'approved'),
('fitrahive', 'morning-dhikr/8', 'Dua for Salvation in The World and Hereafter', 'اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَاْلآخِرَةِ، اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ اللَّهُمَّ اسْتُرْ عَوْرَاتِى وَآمِنْ رَوْعَاتِى. اَللَّهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِيْ، وَعَنْ يَمِيْنِيْ وَعَنْ شِمَالِيْ، وَمِنْ فَوْقِيْ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ', 'allahumma inni as''alukal-''afwa wal-''afiyah fid-dunya wal-akhirah. allahumma inni as''alukal-''afwa wal-''afiyah fi dini wa dunyaya wa ahli wa mali. allahummastur ''awrati wa amin raw''ati. allahummahfadhni min bayni yadayya, wa min khalfi, wa ''an yamini wa ''an shimali, wa min fawqi. wa a''udhu bi ''adhamatika an ughtala min tahti', 'O Allah, indeed I ask You for well-being and safety in this world and the Hereafter. O Allah, indeed I ask You for well-being and safety in my religion, my world, my family and my wealth. O Allah, cover my flaws (faults and things that are not appropriate for others to see) and calm me from fear. O Allah, protect me from the front, behind, right, left and above me. I seek refuge in Your greatness, so that I am not snatched from below me (by snakes or swallowed by the earth, etc., which would cause me to fall).', 'HR. al-Bukhari in al-Adab al-Mufrad No. 1200, Abu Dawud No. 5074, an-Nasa''i VII/282, Ibn Majah No. 3871, al-Hakim 1/517-518, and others from Ibn Umar radhiyallahu ''anhuma', 'morning', 1, 'The Prophet sallallahu ''alayhi wa sallam never left this prayer in the morning and evening. It contains protection and safety for religion, the world, family and property from various kinds of disturbances that come from various directions.', array['dhikr','morning']::text[], 8, 'approved'),
('fitrahive', 'morning-dhikr/9', 'Dua for Protection from Shaytan Whispers', 'اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَاْلأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ، أَشْهَدُ أَنْ لاَ إِلَـهَ إِلاَّ أَنْتَ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِيْ سُوْءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', 'allahumma ''alimal-ghaybi wash-shahadati, fatiras-samawati wal-ard, rabbakulli shayin wa malikahu. ashhadu alla ilaha illa anta, a''udhu bika min sharri nafsi, wa min sharri ash-shaytani wa shirkih. wa an aqtarifa ''ala nafsi su''an aw ajurrahu ila muslim', 'O Allah, Knower of the unseen and the seen, Creator of the heavens and the earth, Lord of all things and their Sovereign. I bear witness that there is no deity worthy of worship except You. I seek refuge in You from the evil of myself, Satan and his soldiers (temptations to commit shirk against Allah), and I (seek refuge in You) from committing evil against myself or dragging it to a Muslim.', 'HR. al-Bukhari in al-Adab al-Mufrad No. 1202, at-Tirmidzi No. 3392 and Abu Dawud No. 5067', 'morning', 1, 'The Prophet Muhammad sallallahu ''alayhi wa sallam said to Abu Bakr ash-Shiddiq radhiyallahu ''anhu ''Say morning and evening and when you are going to sleep''.', array['dhikr','morning']::text[], 9, 'approved'),
('fitrahive', 'morning-dhikr/10', 'Asking for Protection from All Harms', 'بِسْمِ اللَّهِ الَّذِى لاَ يَضُرُّ مَعَ اسْمِهِ شَىْءٌ فِى الأَرْضِ وَلاَ فِى السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', 'bismillahi alladhi la yadurru ma''asmihi shay''un fi''l-ard wa la fi''s-sama''i, wa huwa as-sami''u al-''aleem', 'In the name of Allah with Whose name nothing can harm on earth or in heaven, and He is the All-Hearing, All-Knowing.', 'HR. at-Tirmidzi No. 3388, Abu Dawud No. 5088, Ibn Majah No. 3869, al-Hakim 1/514, and Ahmad No. 446 and 474', 'morning', 3, 'Whoever reads it three times in the morning and evening, then nothing will harm him.', array['dhikr','morning']::text[], 10, 'approved'),
('fitrahive', 'morning-dhikr/11', 'Declaration of Pleasure with Allah, Islam, and the Prophet Muhammad sallallahu ''alayhi wa sallam', 'رَضِيْتُ بِاللهِ رَبًّا، وَبِاْلإِسْلاَمِ دِيْنًا، وَبِمُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا', 'raditu billahi rabba, wa bil-islami dina, wa bi-muhammadin sallallahu ''alayhi wa sallama nabiyya', 'I am pleased with Allah as my Lord, Islam as my religion and Muhammad sallallahu ''alayhi wa sallam as my Prophet (sent by Allah).', 'HR. Ahmad IV/337, Abu Dawud No. 5072, at-Tirmidzi No. 3389, Ibn Majah No. 3870, an-Nasa''i in ''Amalul Yaum wal Lailah No. 4 and Ibnus Sunni No. 68', 'morning', 3, 'Whoever reads it three times in the morning and evening, Allah will give His pleasure to him and the Day of Judgment.', array['dhikr','morning']::text[], 11, 'approved'),
('fitrahive', 'morning-dhikr/12', 'Asking Allah for Guidance', 'يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ، وَأَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ وَلاَ تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ أَبَدًا', 'ya hayyu ya qayyum, bi rahmatika astaghith. wa aslih li sha''ni kullahu wa la takilni ila nafsi tarfata ''aynin abada', 'O Ever-Living, O Self-Sustaining, by Your mercy I seek help, rectify all my affairs and do not leave me to myself even for the blink of an eye.', 'HR. an-Nasa''i in ''Amalul Yaum wal Lailah No. 575, and al-Hakim 1/545, Sahih at-Targhib wat Tarhib 1/417 No. 661, As-Sahihah No. 227, hasan', 'morning', 1, 'The meaning of this prayer is that humans really need Allah and pray that Allah will not leave him even for a moment.', array['dhikr','morning']::text[], 12, 'approved'),
('fitrahive', 'morning-dhikr/13', 'Entering The Morning Upon The Natural Religion of Islam', 'أَصْبَحْنَا عَلَى فِطْرَةِ اْلإِسْلاَمِ وَعَلَى كَلِمَةِ اْلإِخْلاَصِ، وَعَلَى دِيْنِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِيْنَا إِبْرَاهِيْمَ، حَنِيْفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِيْنَ', 'asbahna ''ala fitratil-islam wa ''ala kalimatil-ikhlas, wa ''ala dini nabiyyina muhammadin sallallahu ''alayhi wa sallam, wa ''ala millati abina ibrahima hanifan musliman wa ma kana minal-mushrikin', 'In the morning we are upon the fitrah of Islam, the word of sincerity (the testimony of faith), the religion of our Prophet Muhammad, sallallahu ''alayhi wa sallam, and the religion of our father Abraham, who stood upon the straight path, a Muslim, and was not among the polytheists.', 'HR. Ahmad III/406, 407, ad-Darimi II/292 and Ibnus Sunni in Amalul Yaum wal Lailah No. 34, Mishkat al-Masabih No. 2415, Sahih al-Jami'' as-Saghir No. 4674, sahih', 'morning', 1, '''Fitratil Islam'' means above the sunnah, ''kalimatil Ikhlas'' means the Shahada and ''hanifan'' means the heart is inclined to the straight path and goodness.', array['dhikr','morning']::text[], 13, 'approved'),
('fitrahive', 'morning-dhikr/14', 'Tawheed Dhikr', 'لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ', 'la ilaha illa allah wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir', 'There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs the dominion and all praise. And He is over all things competent.', 'HR al-Bukhari No. 3293 and 6403, Muslim IV/2071 No. 2691 (28), at-Tirmidzi No. 3468, Ibn Majah No. 3798', 'morning', 1, 'Whoever reads it 100 times a day, then for him (the reward) is like freeing ten slaves, writing a hundred good things, removing a hundred bad things from him, getting protection from the devil that day until the evening. It is not that a person can bring better than what he brought unless he did more than that.', array['dhikr','morning']::text[], 14, 'approved'),
('fitrahive', 'morning-dhikr/15', 'Read Tasbih', 'سُبْحَانَ اللهِ وَبِحَمْدِهِ عَدَدَ خَلْقَهِ وَرِضَى نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ', 'subhanallahi wa bihamdihi ''adada khalqihi wa rida nafsihi wa zinata ''arshihi wa midada kalimatihi', 'Glory to Allah, I praise Him as many as the number of His creatures, Glory to Allah according to His pleasure, as pure as the weight of His Throne, and as pure as the ink (which writes) His words.', 'HR. Muslim No. 2726. Sharh Muslim XVII/44. From Juwairiyah binti al-Harits radhiyallahu ''anhuma', 'morning', 3, 'The Prophet, sallallahu ''alayhi wa sallam, told Juwairiyah that the dhikr above has surpassed the dhikr recited by Juwairiyah from after Fajr until Dhuha time.', array['dhikr','morning']::text[], 15, 'approved'),
('fitrahive', 'morning-dhikr/16', 'Dua for Useful Knowledge, Good Sustenance, and Accepted Deeds', 'اللَّهُمَّ إِنِّى أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلاً مُتَقَبَّلاً', 'allahumma inni as''aluka ''ilman nafi''an, wa rizqan tayyiban, wa ''amalan mutaqabbalan', 'O Allah, I really ask You for knowledge that is beneficial, sustenance that is lawful, and deeds that are accepted.', 'HR. Ibnu Majah No. 925, Sahih Ibni Majah 1/152 No. 753 Ibnus Sunni in ''Amalul Yaum wal Lailah No. 54, 110, and Ahmad VI/294, 305, 318, 322. From Ummu Salamah, sahih', 'morning', 1, 'This prayer is recommended in the morning because morning time has more privileges and blessings. As the words of Rasulullah sallallahu ''alayhi wa sallam "O Allah, bless my people in the morning".', array['dhikr','morning']::text[], 16, 'approved'),
('fitrahive', 'morning-dhikr/17', 'Daily Tasbih and Tahmid', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', 'subhanallah wa bihamdihi', 'Glory be to Allah, I praise Him.', 'HR. Muslim No. 2691 and No. 2692, from Abu Hurairah radhiyallahu ''anhu Sharh Muslim XVII/17-18, Sahih at-Targhib wat Tarhib 1/413 No. 653', 'morning', 100, 'Whoever says the phrase ''subhanallah wa bi hamdih'' in the morning and evening 100 times, then no one will come on the Day of Judgement that is better than what he did except the person who said something like or more thant that.', array['dhikr','morning']::text[], 17, 'approved'),
('fitrahive', 'morning-dhikr/18', 'Istighfar 100x a Day', 'أَسْتَغْفِرُ الله وَأَتُوْبُ إِلَيْهِ', 'astaghfirullah wa atubu ilayh', 'I seek forgiveness from Allah and repent to Him.', 'HR. al-Bukhari/Fat-hul Baari XI/101 and Muslim No. 2702', 'morning', 100, 'Ibn ''Umar said: The Messenger of Allah, sallallahu ''alayhi wa sallam, said: ''O people, repent to Allah, for indeed I repent to Him one hundred times a day''.', array['dhikr','morning']::text[], 18, 'approved'),
('fitrahive', 'evening-dhikr/0', 'Ayat al-Kursi', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'allahu la ilaha illa huwa, al-hayyul-qayyum. la ta''khudhuhu sinatun wa la nawm. lahu ma fis-samawati wa ma fil-ard. man dhal-ladhi yashfa''u ''indahu illa bi-idhnihi. ya''lamu ma bayna aydihim wa ma khalfahum. wa la yuhituna bishay''in min ''ilmihi illa bima sha''. wa si''a kursiyyuhu as-samawati wal-ard. wa la ya''udu-hu hifdhuhuma. wa huwa al-''aliyyul-''azim', 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 'HR. at-Tirmidzi: 2879', 'evening', 1, 'Whoever recites this verse in the morning will be protected until the evening. And whoever recites it in the evening will be protected until the morning.', array['dhikr','evening']::text[], 0, 'approved'),
('fitrahive', 'evening-dhikr/1', 'Al-Ikhlas', 'قُلْ هُوَ ٱللَّهُ أَحَدٌ (1) ٱللَّهُ ٱلصَّمَدُ (2) لَمْ يَلِدْ وَلَمْ يُولَدْ (3) وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ (4)', 'qul huwa allahu ahad (1) allahu samad (2) lam yalid wa lam yulad (3) wa lam yakun lahu kufuwan ahad (4)', 'Say, "He is Allah , [who is] One, (1) Allah , the Eternal Refuge. (2) He neither begets nor is born, (3) Nor is there to Him any equivalent." (4)', 'HR. Abu Dawud No. 4241', 'evening', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','evening']::text[], 1, 'approved'),
('fitrahive', 'evening-dhikr/2', 'Al-Falaq', 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ (1) مِن شَرِّ مَا خَلَقَ (2) وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ (3) وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ (4) وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ (5)', 'qul a''udhu birabbil-falaq (1) min sharri ma khalaq (2) wa min sharri ghasiqin idha waqab (3) wa min sharri naffathati fil-''uqad (4) wa min sharri hasidin idha hasad (5)', 'Say, "I seek refuge in the Lord of daybreak (1) From the evil of that which He created (2) And from the evil of darkness when it settles (3) And from the evil of the blowers in knots (4) And from the evil of an envier when he envies." (5)', 'HR. Abu Dawud No. 4241', 'evening', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','evening']::text[], 2, 'approved'),
('fitrahive', 'evening-dhikr/3', 'An-Nas', 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ (1) مَلِكِ ٱلنَّاسِ (2) إِلَٰهِ ٱلنَّاسِ (3) مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ (4) ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ (5) مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ (6)', 'qul a''udhu birabbin-nas (1) malikin-nas (2) ilahin-nas (3) min sharri al-waswasi al-khannas (4) alladhi yuwaswisu fi sudurin-nas (5) mina al-jinnati wan-nas (6)', 'Say, "I seek refuge in the Lord of mankind, (1) The King of mankind. (2) The God of mankind, (3) From the evil of the whisperer who withdraws, (4) Who whispers in the breasts of mankind, (5) Of the jinn and mankind." (6)', 'HR. Abu Dawud No. 4241', 'evening', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','evening']::text[], 3, 'approved'),
('fitrahive', 'evening-dhikr/4', 'Entering the Evening in the Kingdom of Allah and Seeking His Protection', 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ للهِ، وَالْحَمْدُ للهِ، لَا إِلَهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُبِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُبِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُبِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', 'amsayna wa amsal-mulku lillahi wal-hamdu lillahi, la ilaha illa allah wahdahu la sharika lahu, lahu al-mulku wa lahu al-hamdu wa huwa ''ala kulli shay''in qadir. rabbi as''aluka khayra ma fi hadhihil-laylah wa khayra ma ba''daha, wa a''udhu bika min sharri ma fi hadhihil-laylah wa sharri ma ba''daha. rabbi a''udhu bika mina al-kasali wa su''il-kibar. rabbi a''udhu bika min ''adhabin fin-nar wa ''adhabin fil-qabr', 'We have entered the evening and the dominion belongs to Allah, and all praise is for Allah. There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs the dominion and to Him is praise, and He is over all things competent. My Lord, I ask You for the good of this night and the good of what follows it, and I seek refuge in You from the evil of this night and the evil of what follows it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from the punishment of the Fire and the punishment of the grave.', 'HR. Muslim No. 2723 (75), Abu Dawud No. 5071, and at-Tirmidzi 3390, sahih from Abdullah Ibn Mas''ud', 'evening', 1, 'Seeking protection from evil is prioritized, the principle that shows the importance of this is: "Preventing harm is more important and prioritized than bringing about good."', array['dhikr','evening']::text[], 4, 'approved'),
('fitrahive', 'evening-dhikr/5', 'Entering the Evening by Seeking Allah''s Mercy', 'اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا،وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيْرُ', 'allahumma bika amsayna, wa bika asbahna, wa bika nahya, wa bika namutu wa ilayka al-masir', 'O Allah, by Your grace and help we have entered the evening, and by Your grace and help we enter the morning. By Your grace and help we live and by Your will we die. And to You is the final return (of all creatures).', 'HR. al-Bukhari in al-Adab al-Mufrad No. 1199, this wording is the wording of al-Bukhari at-Tirmidzi No. 3391, Abu Dawud No. 5068, Ahmad 11/354, Ibn Majah No. 3868', 'evening', 1, 'Everything we do from morning to evening, from the beginning of our lives until we die, is all under Allah''s control and to Him we return.', array['dhikr','evening']::text[], 5, 'approved'),
('fitrahive', 'evening-dhikr/6', 'The Master of Seeking Forgiveness', 'اَللَّهُمَّ أَنْتَ رَبِّيْ ، لَا إِلٰـهَ إِلاَّ أَنْتَ خَلَقْتَنِيْ وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوْءُ لَكَ بِنِعْمتِكَ عَلَيَّ ، وَأَبُوْءُ بِذَنْبِيْ فَاغْفِرْ لِيْ ، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ', 'allahumma anta rabbi la ilaha illa anta khalaqtani wa ana ''abduka wa ana ''ala ''ahdika wa wa''dika mastata''tu a''udhu bika min sharri ma sana''tu abu''u laka bini''matika ''alayya wa abu''u bidhanbi faghfir li fa innahu la yaghfirudh-dhunuba illa anta', 'O Allah, You are my Lord, there is no deity worthy of worship except You, You created me and I am Your servant. I will be true to my covenant and promise to You as much as I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favor upon me and I acknowledge my sin, therefore, forgive me. Indeed, there is no one who can forgive sins except You.', 'HR. al-Bukhari No. 6306, 6323, Ahmad IV/122-125, an-Nasa''i VIII/279-280', 'evening', 1, 'Whoever recites it with certainty in the evening, and then he dies, he will enter Paradise, and likewise if (recited) in the morning.', array['dhikr','evening']::text[], 6, 'approved'),
('fitrahive', 'evening-dhikr/7', 'Prayer for Health and Protection', 'اَللَّهُمَّ عَافِنِيْ فِيْ بَدَنِيْ ، اَللَّهُمَّ عَافِنِيْ فِيْ سَمْعِيْ ، اَللَّهُمَّ عَافِنِيْ فِيْ بَصَرِيْ ، لَا إِلَـهَ إِلَّا أَنْتَ ، اَللَّهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِوَالْفَقْرِ ، وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ ، لَا إِلَـهَ إِلَّا أَنْتَ', 'allahumma ''afini fi badani, allahumma ''afini fi sam''i, allahumma ''afini fi basari, la ilaha illa anta. allahumma inni a''udhu bika minal-kufri wal-faqr, allahumma inni a''udhu bika min ''adhabil-qabr, la ilaha illa anta', 'O Allah, protect my body (from illness and from what I do not want). O Allah, protect my hearing (from illness and disobedience or from what I do not want). O Allah, protect my sight, there is no deity worthy of worship except You. O Allah, indeed I seek refuge in You from disbelief and poverty. I seek refuge in You from the punishment of the grave, there is no deity worthy of worship except You.', 'HR. al-Bukhari in Sahih al-Adab al-Mufrad No. 701, Abu Dawud No. 5090, Ahmad V/42, hasan', 'evening', 1, 'By asking Allah to grant us well-being in our bodies, we ask to be healed from all physical and spiritual illnesses, so that we have a healthy body and a pure heart, and therefore use this healthy body in a way that pleases Allah.', array['dhikr','evening']::text[], 7, 'approved'),
('fitrahive', 'evening-dhikr/8', 'Prayer for Safety in This World and the Hereafter', 'اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَاْلآخِرَةِ، اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِيْنِيْ وَدُنْيَايَ وَأَهْلِيْ وَمَالِيْ اللَّهُمَّ اسْتُرْ عَوْرَاتِى وَآمِنْ رَوْعَاتِى. اَللَّهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِيْ، وَعَنْ يَمِيْنِيْ وَعَنْ شِمَالِيْ، وَمِنْ فَوْقِيْ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ', 'allahumma inni as''alukal-''afwa wal-''afiyah fid-dunya wal-akhirah. allahumma inni as''alukal-''afwa wal-''afiyah fi dini wa dunyaya wa ahli wa mali. allahummastur ''awrati wa amin raw''ati. allahummahfadhni min bayni yadayya wa min khalfi wa ''an yamini wa ''an shimali wa min fawqi wa a''udhu bi ''adhamatika an ughtala min tahti', 'O Allah, indeed I ask You for well-being and safety in this world and the Hereafter. O Allah, indeed I ask You for well-being and safety in my religion, my world, my family and my wealth. O Allah, cover my flaws (faults and things that are not appropriate for others to see) and calm me from fear. O Allah, protect me from the front, behind, right, left and above me. I seek refuge in Your greatness, so that I am not snatched from below me (by snakes or swallowed by the earth, etc., which would cause me to fall).', 'HR. al-Bukhari in al-Adab al-Mufrad No. 1200, Abu Dawud No. 5074, an-Nasa''i VII/282, Ibn Majah No. 3871, al-Hakim 1/517-518, and others from Ibn Umar radhiyallahu ''anhuma', 'evening', 1, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, never left this supplication in the morning and evening. It contains protection and safety for religion, the world, family, and wealth from various kinds of disturbances that come from all directions.', array['dhikr','evening']::text[], 8, 'approved'),
('fitrahive', 'evening-dhikr/9', 'Prayer for Seeking Protection from the Whispers of Satan', 'اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَاوَاتِ وَاْلأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ، أَشْهَدُ أَنْ لاَ إِلَـهَ إِلاَّ أَنْتَ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِيْ سُوْءًا أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ', 'allahumma ''alimal-ghaybi wash-shahadati, fatiras-samawati wal-ard, rabbakulli shayin wa malikahu. ashhadu alla ilaha illa anta, a''udhu bika min sharri nafsi, wa min sharri ash-shaytani wa shirkih. wa an aqtarifa ''ala nafsi su''an aw ajurrahu ila muslim', 'O Allah, Knower of the unseen and the seen, Creator of the heavens and the earth, Lord of all things and their Sovereign. I bear witness that there is no deity worthy of worship except You. I seek refuge in You from the evil of myself, Satan and his soldiers (temptations to commit shirk against Allah), and I (seek refuge in You) from committing evil against myself or dragging it to a Muslim.', 'HR. al-Bukhari in al-Adab al-Mufrad No. 1202, at-Tirmidzi No. 3392 and Abu Dawud No. 5067', 'evening', 1, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said to Abu Bakr as-Siddiq, may Allah be pleased with him, "Say it morning and evening and when you want to sleep."', array['dhikr','evening']::text[], 9, 'approved'),
('fitrahive', 'evening-dhikr/10', 'Remembrance to Be Protected from All Dangers', 'بِسْمِ اللَّهِ الَّذِى لاَ يَضُرُّ مَعَ اسْمِهِ شَىْءٌ فِى الأَرْضِ وَلاَ فِى السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', 'bismillahilladhi la yadurru ma''asmihi shay''un fil-ardi wa la fis-sama'' wa huwas-sami''ul-''alim', 'In the name of Allah, with whose name nothing in the earth or the heavens can cause harm, and He is the All-Hearing, the All-Knowing.', 'HR. at-Tirmidzi No. 3388, Abu Dawud No. 5088, Ibn Majah No. 3869, al-Hakim 1/514, and Ahmad No. 446 and 474', 'evening', 3, 'Whoever recites it three times in the morning and evening, nothing will harm him.', array['dhikr','evening']::text[], 10, 'approved'),
('fitrahive', 'evening-dhikr/11', 'Declaration of Contentment with Allah, Islam, and the Prophet Muhammad sallallahu ''alayhi wa sallam', 'رَضِيْتُ بِاللهِ رَبًّا، وَبِاْلإِسْلاَمِ دِيْنًا، وَبِمُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا', 'raditu billahi rabba, wa bil-islami dina, wa bi-muhammadin sallallahu ''alayhi wa sallama nabiyya', 'I am pleased with Allah as my Lord, Islam as my religion, and Muhammad, sallallahu ''alayhi wa sallam, as my Prophet.', 'HR. Ahmad IV/337, Abu Dawud No. 5072, at-Tirmidzi No. 3389, Ibn Majah No. 3870, an-Nasa''i in ''Amalul Yaum wal Lailah No. 4 and Ibnus Sunni No. 68', 'evening', 3, 'Whoever recites it three times in the morning and evening, Allah will grant His pleasure to him on the Day of Resurrection.', array['dhikr','evening']::text[], 11, 'approved'),
('fitrahive', 'evening-dhikr/12', ' Asking for Guidance from Allah', 'يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ، وَأَصْلِحْ لِيْ شَأْنِيْ كُلَّهُ وَلاَ تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ أَبَدًا', 'ya hayyu ya qayyum, bi-rahmatika astaghith, wa aslih li sha''ni kullahu wa la takilni ila nafsi tarfata ''aynin abada', 'O Ever-Living, O Self-Sustaining, by Your mercy I seek help, rectify all my affairs and do not leave me to myself even for the blink of an eye.', 'HR. an-Nasa''i in ''Amalul Yaum wal Lailah No. 575, and al-Hakim 1/545, see Sahih at-Targhib wat Tarhib 1/417 No. 661, As-Sahihah No. 227, hasan', 'evening', 1, 'The meaning of this supplication is that humans are in dire need of Allah and pray that Allah does not abandon them even for a moment.', array['dhikr','evening']::text[], 12, 'approved'),
('fitrahive', 'evening-dhikr/13', 'Entering the Evening on the Natural Disposition of Islam', 'أَمْسَيْنَا عَلَى فِطْرَةِ اْلإِسْلاَمِ وَعَلَى كَلِمَةِ اْلإِخْلاَصِ، وَعَلَى دِيْنِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِيْنَا إِبْرَاهِيْمَ، حَنِيْفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِيْنَ', 'amsayna ''ala fitratil-islam wa ''ala kalimatil-ikhlas, wa ''ala dini nabiyyina muhammadin sallallahu ''alayhi wa sallam, wa ''ala millati abina ibrahima hanifan musliman wa ma kana minal-mushrikin', 'In the evening we are upon the fitrah of Islam, the word of sincerity (the testimony of faith), the religion of our Prophet Muhammad, sallallahu ''alayhi wa sallam, and the religion of our father Abraham, who stood upon the straight path, a Muslim, and was not among the polytheists.', 'HR. Ahmad III/406, 407, ad-Darimi II/292 and Ibnus Sunni in Amalul Yaum wal Lailah No. 34, Mishkat al-Masabih No. 2415, Sahih al-Jami'' as-Saghir No. 4674, sahih', 'evening', 1, '''Fitratil Islam'' means upon the Sunnah, ''kalimatil ikhlas'' means the testimony of faith, and ''hanifan'' means a heart inclined towards the straight path and goodness.', array['dhikr','evening']::text[], 13, 'approved'),
('fitrahive', 'evening-dhikr/14', 'Remembrance of the Oneness of Allah', 'لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ', 'la ilaha illa allah wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir', 'There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs the dominion and all praise. He is over all things competent.', 'HR al-Bukhari No. 3293 and 6403, Muslim IV/2071 No. 2691 (28), at-Tirmidzi No. 3468, Ibn Majah No. 3798', 'evening', 1, 'Whoever says this dhikr 100 times a day, it is like freeing 10 slaves, 100 good deeds are recorded for him, 100 mistakes are erased for him, he will be protected from the disturbances of Satan from morning until evening, and no one is better than what he does except someone who practices more than that.', array['dhikr','evening']::text[], 14, 'approved'),
('fitrahive', 'evening-dhikr/15', 'Reciting Praise to Allah', 'سُبْحَانَ اللهِ وَبِحَمْدِهِ عَدَدَ خَلْقَهِ وَرِضَى نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ', 'subhanallahi wa bihamdihi ''adada khalqihi wa rida nafsihi wa zinata ''arshihi wa midada kalimatihi', 'Glory be to Allah, as many as His creations, Glory be to Allah as much as His pleasure, Glory be to Allah as much as the weight of His Throne, and as much as the ink of His written words.', 'HR. Muslim No. 2726. Sharh Muslim XVII/44. From Juwairiyah bint al-Harith radhiyallahu ''anha', 'evening', 3, 'The Prophet, sallallahu ''alayhi wa sallam, told Juwairiyah that the dhikr above has surpassed the dhikr recited by Juwairiyah from after Fajr until Dhuha time.', array['dhikr','evening']::text[], 15, 'approved'),
('fitrahive', 'evening-dhikr/16', 'Daily Praise (Tasbih and Alhamdulillah)', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', 'subhanallahi wa bihamdihi', 'Glory be to Allah, and praise be to Him.', 'HR. Muslim No. 2691 and No. 2692, from Abu Hurairah radhiyallahu ''anhu Sharh Muslim XVII/17-18, Sahih at-Targhib wat Tarhib 1/413 No. 653', 'evening', 100, 'Whoever says "Subhanallah wa bihamdihi" 100 times in the morning and evening, then nothing will come on the Day of Judgment better than what he has done except one who says the same or more than that.', array['dhikr','evening']::text[], 16, 'approved'),
('fitrahive', 'evening-dhikr/17', 'Seeking Forgiveness 100 Times a Day', 'أَسْتَغْفِرُ الله وَأَتُوْبُ إِلَيْهِ', 'astaghfirullah wa atubu ilayh', 'I seek forgiveness from Allah and repent to Him.', 'HR. al-Bukhari/Fat-hul Baari XI/101 and Muslim No. 2702', 'evening', 100, 'Ibn ''Umar said: The Messenger of Allah, sallallahu ''alayhi wa sallam, said: ''O people, repent to Allah, for indeed I repent to Him one hundred times a day.''', array['dhikr','evening']::text[], 17, 'approved'),
('fitrahive', 'evening-dhikr/18', 'Prayer for Protection from the Evil of Allah''s Creation', 'أَعُوْذُ بِكَلِمَاتِ اللهِ التَّآمَّاتِ مِنْ شَرِّ مَا خَلَقَ', 'a''udhu bikalimatillahit-tammati min sharri ma khalaq', 'I seek refuge in the perfect words of Allah from the evil of what He has created.', 'HR. Ahmad 11/290, an-Nasa''i in ''Amalul Yaum wal Lailah No. 596, Sahih at-Targhib wat Tarhib 1/412 No. 652, Sahih al-Jami'' as-Saghir No. 6427', 'evening', 3, 'Whoever recites it three times in the evening, they will not be afflicted with fever that night.', array['dhikr','evening']::text[], 18, 'approved'),
('fitrahive', 'dhikr-after-salah/0', 'Istighfar', 'أَسْتَغْفِرُ اللَّهَ', 'astaghfirullah', 'I seek forgiveness from Allah.', 'HR. Muslim No. 591', 'after_prayer', 3, 'When the Messenger of Allah, sallallahu ''alayhi wa sallam, finished his prayer, he would seek forgiveness three times and recite the dhikr above. Al-Auza''i stated that the recitation of istighfar is ''Astaghfirullah, Astaghfirullah.''', array['dhikr','after_prayer']::text[], 0, 'approved'),
('fitrahive', 'dhikr-after-salah/1', 'Allah, The Giver of Peace', 'اَللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَاْلإِكْرَامِ', 'allahumma antas-salam wa minkas-salam tabarakta ya dhal-jalali wal-ikram', 'O Allah, You are Peace, and from You is peace. Blessed are You, O Possessor of majesty and honor.', 'HR. Muslim No. 591', 'after_prayer', 1, 'When the Messenger of Allah, sallallahu ''alayhi wa sallam, finished his prayer, he would seek forgiveness three times and recite the dhikr above. Al-Auza''i stated that the recitation of istighfar is ''Astaghfirullah, Astaghfirullah.''', array['dhikr','after_prayer']::text[], 1, 'approved'),
('fitrahive', 'dhikr-after-salah/2', 'Allah, The Preventer and The Giver of All Things', 'لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ، اَللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ', 'la ilaha illa allah wahdahu la sharika lah, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir. allahumma la mani''a lima a''tayta wa la mu''tiya lima mana''ta wa la yanfa''u dhal-jaddi minkal-jaddu', 'There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs dominion and praise, and He is over all things competent. O Allah, there is no preventer of what You give, and no giver of what You withhold, and wealth and honor do not benefit their possessor (except faith and righteous deeds that save from punishment). Only from You is wealth and honor.', 'HR. Bukhari No. 844 and Muslim No. 593', 'after_prayer', 1, null, array['dhikr','after_prayer']::text[], 2, 'approved'),
('fitrahive', 'dhikr-after-salah/3', 'Allah, The Possessor of All and The Only One Worthy of Worship', 'لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللهِ، لاَ إِلَـهَ إِلاَّ اللهُ، وَلاَ نَعْبُدُ إِلاَّ إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لاَ إِلَـهَ إِلاَّ اللهُ مُخْلِصِيْنَ لَهُ الدِّيْنَ وَلَوْ كَرِهَ الْكَافِرُوْنَ', 'la ilaha illa allah wahdahu la sharika lah. lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir. la hawla wa la quwwata illa billah. la ilaha illa allah wa la na''budu illa iyyah. lahun-ni''mah wa lahul-fadl wa lahuth-thana''ul-hasan. la ilaha illa allah mukhlisina lahud-dina wa law karihal-kafirun', 'There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs dominion and praise, and He is over all things competent. There is no power and no strength except by Allah. There is no deity worthy of worship except Allah, and we do not worship except Him. To Him belongs all favor, grace, and good praise. There is no deity worthy of worship except Allah, making our religion sincerely for Him, even if the disbelievers dislike it.', 'HR. Muslim No. 594', 'after_prayer', 1, '''Abdullah bin Zubair said, "The Prophet, sallallahu ''alayhi wa sallam, used to recite the tahlil (laa ilaha illallah) at the end of the prayer."', array['dhikr','after_prayer']::text[], 3, 'approved'),
('fitrahive', 'dhikr-after-salah/4', 'Tasbih', 'سُبْحَانَ اللهِ', 'subhanallah', 'Glory be to Allah', null, 'after_prayer', 33, null, array['dhikr','after_prayer']::text[], 4, 'pending'),
('fitrahive', 'dhikr-after-salah/5', 'Tahmid', 'الْحَمْدُ لِلَّهِ', 'alhamdulillah', 'All praise is for Allah', null, 'after_prayer', 33, null, array['dhikr','after_prayer']::text[], 5, 'pending'),
('fitrahive', 'dhikr-after-salah/6', 'Takbir', 'اللهُ أَكْبَرُ', 'allahu akbar', 'Allah is the Greatest', null, 'after_prayer', 33, null, array['dhikr','after_prayer']::text[], 6, 'pending'),
('fitrahive', 'dhikr-after-salah/7', 'There is No Partner for Allah, and To Him Belongs All Things', 'لاَ إِلَـهَ إِلاَّ اللهُ وَحْدَهُ لاَ شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرُ', 'la ilaha illa allah wahdahu la sharika lah. lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir', 'There is no deity worthy of worship except Allah alone, He has no partner. To Him belongs dominion and praise, and He is over all things competent.', 'Sharh Shahih Muslim, 5: 84', 'after_prayer', 1, 'Whoever recites the dhikr above, his sins will be forgiven, even if they are as numerous as the foam on the ocean. Imam Nawawi, may Allah have mercy on him, said that the text of the hadith indicates that ''Subhanallah'', ''Alhamdulillah'', and ''Allahu akbar'' are each recited 33 times separately.', array['dhikr','after_prayer']::text[], 7, 'approved'),
('fitrahive', 'dhikr-after-salah/8', 'Ayat al-Kursi', 'ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ', 'allahu la ilaha illa huwa, al-hayyul-qayyum. la ta''khudhuhu sinatun wa la nawm. lahu ma fis-samawati wa ma fil-ard. man dhal-ladhi yashfa''u ''indahu illa bi-idhnihi. ya''lamu ma bayna aydihim wa ma khalfahum. wa la yuhituna bishay''in min ''ilmihi illa bima sha''. wa si''a kursiyyuhu as-samawati wal-ard. wa la ya''udu-hu hifdhuhuma. wa huwa al-''aliyyul-''azim', 'Allah - there is no deity except Him, the Ever-Living, the Sustainer of [all] existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is [presently] before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 'HR. an-Nasai in Al-Kubro 9: 44. This hadith is declared sahih by Ibn Hibban, as mentioned by Ibn Hajar in Bulugh al-Maram', 'after_prayer', 1, 'Whoever recites Ayat al-Kursi after finishing the prayer, nothing will prevent him from entering Paradise except death.', array['dhikr','after_prayer']::text[], 8, 'approved'),
('fitrahive', 'dhikr-after-salah/9', 'Al-Ikhlas', 'قُلْ هُوَ ٱللَّهُ أَحَدٌ (1) ٱللَّهُ ٱلصَّمَدُ (2) لَمْ يَلِدْ وَلَمْ يُولَدْ (3) وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ (4)', 'qul huwa allahu ahad (1) allahu samad (2) lam yalid wa lam yulad (3) wa lam yakun lahu kufuwan ahad (4)', 'Say, "He is Allah , [who is] One, (1) Allah , the Eternal Refuge. (2) He neither begets nor is born, (3) Nor is there to Him any equivalent." (4)', 'HR. Abu Dawud No. 1523 and an-Nasa''i No. 1337. Al-Hafiz Abu Tahir said that the chain of this hadith is hasan', 'after_prayer', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','after_prayer']::text[], 9, 'approved'),
('fitrahive', 'dhikr-after-salah/10', 'Al-Falaq', 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ (1) مِن شَرِّ مَا خَلَقَ (2) وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ (3) وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ (4) وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ (5)', 'qul a''udhu birabbil-falaq (1) min sharri ma khalaq (2) wa min sharri ghasiqin idha waqab (3) wa min sharri naffathati fil-''uqad (4) wa min sharri hasidin idha hasad (5)', 'Say, "I seek refuge in the Lord of daybreak (1) From the evil of that which He created (2) And from the evil of darkness when it settles (3) And from the evil of the blowers in knots (4) And from the evil of an envier when he envies." (5)', 'HR. Abu Dawud No. 1523 and an-Nasa''i No. 1337. Al-Hafiz Abu Tahir said that the chain of this hadith is hasan', 'after_prayer', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','after_prayer']::text[], 10, 'approved'),
('fitrahive', 'dhikr-after-salah/11', 'An-Nas', 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ (1) مَلِكِ ٱلنَّاسِ (2) إِلَٰهِ ٱلنَّاسِ (3) مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ (4) ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ (5) مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ (6)', 'qul a''udhu birabbin-nas (1) malikin-nas (2) ilahin-nas (3) min sharri al-waswasi al-khannas (4) alladhi yuwaswisu fi sudurin-nas (5) mina al-jinnati wan-nas (6)', 'Say, "I seek refuge in the Lord of mankind, (1) The King of mankind. (2) The God of mankind, (3) From the evil of the whisperer who withdraws, (4) Who whispers in the breasts of mankind, (5) Of the jinn and mankind." (6)', 'HR. Abu Dawud No. 1523 and an-Nasa''i No. 1337. Al-Hafiz Abu Tahir said that the chain of this hadith is hasan', 'after_prayer', 3, 'The Messenger of Allah, sallallahu ''alayhi wa sallam, said: Recite Qul huwallahu ahad, and Al-Mu''awwidhatayn (Al-Falaq and An-Nas) in the evening and morning three times, and it will suffice you (protect you) from everything.', array['dhikr','after_prayer']::text[], 11, 'approved'),
('fitrahive', 'dhikr-after-salah/12', 'Supplication for Beneficial Knowledge, Good Provision, and Accepted Deeds', 'اللَّهُمَّ إِنِّى أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلاً مُتَقَبَّلاً', 'allahumma inni as''aluka ''ilman nafi''an, wa rizqan tayyiban, wa ''amalan mutaqabbalan', 'O Allah, I ask You for beneficial knowledge, good provision, and accepted deeds.', 'HR. Ibn Majah No. 925 and Ahmad 6: 305, 322. Al-Hafiz Abu Tahir said that this hadith is sahih', 'after_prayer', 1, 'Beneficial knowledge is a provision that makes life easier, obtaining good provision is a person''s goal in working, and accepted deeds are the hope of every person who performs good deeds. Therefore, a servant should always ask for these 3 things every morning before starting their various activities.', array['dhikr','after_prayer']::text[], 12, 'approved')
